    "glossary": [
      [
        "EPS",
        "earnings per share — a company's profit divided by its share count; the number Wall Street forecasts and compares against."
      ],
      [
        "cons.",
        "'consensus' — the average analyst forecast. Markets move on the RESULT vs this expectation, not the result alone."
      ],
      [
        "MoM",
        "month-over-month — compared with the previous month."
      ],
      [
        "FOMC",
        "the US Federal Reserve committee that sets interest rates — its decisions move nearly every market."
      ],
      [
        "risk-off",
        "money rotating OUT of risky assets (stocks, crypto) into safe havens (cash, gold, dollar). 'Transition' means it's only just starting."
      ],
      [
        "risk-on",
        "money comfortable buying risky assets like stocks and crypto; safe havens get sold."
      ],
      [
        "hawkish",
        "leaning toward higher rates / tighter policy — generally a headwind for stocks."
      ],
      [
        "dovish",
        "leaning toward lower rates / easier policy — generally a tailwind for stocks."
      ],
      [
        "CPI",
        "the headline inflation reading (consumer price index) — moves rate expectations and therefore stocks and bonds."
      ],
      [
        "yield",
        "the interest rate on a bond; rising yields make bonds more attractive than stocks and raise borrowing costs."
      ],
      [
        "breadth",
        "how many stocks are participating in a move; narrow breadth means a few names are masking a weak market underneath."
      ],
      [
        "safe haven",
        "assets investors buy when scared (gold, the dollar, Treasuries) — a rising safe-haven bid signals risk-off."
      ]
    ]
